registerItem({
  id: 450183,
  onEquip(ctx) {
    let $hp, $sp;
    $hp = 30 * (ctx.min(ctx.getParam("BaseLevel"), 100) / 5);
    if (ctx.getParam("BaseLevel") >= 30) {
      $hp = $hp + 80;
      $sp = 20;
    }
    if (ctx.getParam("BaseLevel") >= 45) {
      $hp = $hp + 150;
      $sp = $sp + 30;
    }
    if (ctx.getParam("BaseLevel") >= 85) {
      $hp = $hp + 250;
      $sp = $sp + 50;
    }
    ctx.bonus("bMaxHP", 150 + $hp);
    ctx.bonus("bMaxSP", 20 + $sp);

  },
});

